        "meaning": "यह जीव अपने पूर्वोपार्जित शुभाशुभ कर्मों के फल भोगने के लिए अकेला ही जन्म लेता है और अकेला ही इस देह को छोड़कर परलोक जाता है। निश्चय नय से इस जीव का संसार में कोई भी वास्तविक सगा, सम्बन्धी अथवा साथी नहीं है।"
