        "meaning": "जिस देह (शरीर) के साथ जीव का इतना घनिष्ठ संबंध रहा कि जन्म से मरण तक एक जैसा प्रतीत होता है, जब वह देह ही अपनी नहीं है और यहीं छूट जाती है, तो फिर घर, धन-दौलत, परिजन और मित्र अपने कैसे हो सकते हैं? वे सब तो सर्वथा भिन्न और पर-पदार्थ हैं।"
