        "meaning": "जब वीतरागी सद्गुरु के उपदेश से यह जीव जागृत होता है और उसकी मिथ्यात्व व मोह रूपी निद्रा शांत होती है, तब सम्यग्दर्शन, ज्ञान और चारित्र रूपी उपाय प्रकट होते हैं, जिनसे नवीन कर्मरूपी चोरों का आत्मा में आना (आस्रव) रुक जाता है, इसे ही 'संवर' कहते हैं।"
