        "meaning": "जो भव्य आत्मा नित्य इन बारह भावनाओं का शांत चित्त से चिन्तन-मनन करता है, उसका मन समस्त आकुलताओं से छूटकर परम शांति को प्राप्त होता है, और वह संसार के समस्त कर्म-बंधनों को काटकर अविनाशी मोक्षधाम (शिवपुर) को प्राप्त करता है।"
