        "meaning": "जो केवल ज्ञान-दर्शन रूप चेतना और अतीन्द्रिय आनंद स्वरूप हैं, राग-द्वेष को जीतने वाले उन जिनेंद्र परमात्मा को नमस्कार हो। जिनका आत्म-प्रकाश नित्य और शाश्वत रूप से प्रकाशित है, उन सिद्ध परमात्मा को मेरा कोटिशः वंदन हो।"
