        "meaning": "जिनके चरणों के नख, नम्र देवों और असुरों के मुकुटों में लगे रत्नों की प्रभा से उज्ज्वल हैं, जो प्रवचन रूपी समुद्र के चंद्रमा के समान स्थायी हैं, जो जिन, सिद्ध, सूर्य और पाठक साधु हैं, तथा योगीजनों द्वारा स्तुत्य हैं, वे पांचों गुरु आपका मंगल करें।"
