        "meaning": "हे देव! संसार के समस्त प्राणियों के प्रति मेरे अंतःकरण में आत्मीय मैत्री भाव रहे, गुणीजनों को देखकर मन में परम प्रमोद व उल्लास का संचार हो, दुखी और पीड़ित जीवों पर निरंतर करुणा की अमृत-धारा बहे, तथा विपरीत आचरण करने वाले दुर्जनों के प्रति उपेक्षा व मध्यस्थ भाव रहे।"
