        "meaning": "हे भव्य प्राणियों! अष्टान्हिका महापर्व के आठों दिनों तक अत्यंत उत्साह और श्रद्धापूर्वक श्री सिद्धचक्र महामंडल विधान की आराधना करो, जिसका साक्षात अनुपम फल महासती मैनासुंदरी ने प्राप्त किया था। मैनासुंदरी एक परम धर्मनिष्ठ सती थीं, जिनके पति राजा श्रीपाल कुष्ठ रोग से पीड़ित थे। पति की यह दारुण दशा देखकर वे रात-दिन व्याकुल रहती थीं और उन्हें क्षणभर भी चैन नहीं मिलता था।"
